from pathlib import Path
import json,hashlib,shutil,datetime
r=Path.cwd();p=r/'workspace-desktop/test/trajectory145-integration.cjs';s=p.read_text(encoding='utf8');out=r/'docs/publication145'
shutil.copy2(r/'build/trajectory145-app/result.json',r/'build/trajectory145-export-failure.json');shutil.copy2(r/'build/trajectory145-app-resume.log',r/'build/trajectory145-export-failure.log')
