(r/'workspace-desktop/test/trajectory145-resume-integration.cjs').write_text(resumed,encoding='utf8')
exposed=s.replace('trajectory145-app','exposed145-app').replace('DRIFT145_RESUME','EXPOSED145_RESUME').replace('source145.json','source145-exposed.json').replace('trajectory-return','exposed-return')
