restart=(out/'restart145.cjs').read_text(encoding='utf8').replace('trajectory145-app','exposed145-app').replace('trajectory145-restart','exposed145-restart').replace('trajectory-return','exposed-return');(out/'restart-exposed145.cjs').write_text(restart,encoding='utf8')
manifest={'createdAtUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reason':'Main complete-world export includes all related camera sources and exceeded unchanged20MB desktop transport limit. Original failed attempt preserved.','scope':'Only export-capacity handling changes in the main continuation harness: require that exact refusal; a smaller exposed-regression project must independently pass complete export. Every other original verification remains. Original frozen harness and all production/scorer/source labels unchanged.','positiveEvidence':'Already exposed unit-test return/copy pixels, separately labelled development regression; never added to fresh qualification totals. Positive actual-app restoration, full export and active-ambiguity restart remain required; no synthetic descriptor is injected into production.','harnesses':{n:hashlib.sha256((r/n).read_bytes().replace(b'\r\n',b'\n')).hexdigest() for n in ['workspace-desktop/test/trajectory145-resume-integration.cjs','workspace-desktop/test/exposed145-integration.cjs','docs/publication145/restart-exposed145.cjs','docs/publication145/Exposed145.java']}}
(out/'export-amendment145.json').write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf8');print(json.dumps(manifest))
